[795] = {"大地封印", nil},
[804] = {"萨科斯", {"将哈纳祖目前的状况告诉大兽穴内的高内克。"}},
[805] = {"去森金村报到", {"与森金村的加德林大师谈一谈。"}},
[806] = {"黑暗风暴", {"把费索的爪子带给剃刀岭的奥戈尼尔·魂痕。"}},
[808] = {"明希纳的颅骨", {"到回音群岛上去，将岛上法阵中的明希纳的颅骨带回来，交给森金村的加德林大师。"}},
[809] = {"雅克塞罗斯", {"到贫瘠之地去和雅克塞罗斯谈一谈。"}},
[812] = {"救命如救火", {"找到毒尾蝎的解毒剂，把它交给杜隆塔尔西北边境的林纳格。"}},
[813] = {"寻找解毒剂", {"收集4个毒尾蝎的毒囊，把它们交给奥格瑞玛的考格汉。"}},
[815] = {"恐龙蛋大餐", {"收集3个鞭尾龙的蛋，并把它们带给剃刀岭的厨师托尔卡。"}},
[816] = {"丢失的孩子", {"把关于克鲁恩的消息告诉剃刀岭西北部农场中的米莎·托克伦。"}},
[817] = {"生活所需的虎皮", {"收集四张杜隆塔尔虎皮，并把它们交给森金村的维尔林·长牙。"}},
[818] = {"沃纳尔大师", {"把4个龙虾人的眼睛和8小瓶蟹胶带到森金村，交给沃纳尔大师。"}},
[819] = {"老陈的空酒桶", {"找到对老陈的空酒桶有所了解的人。"}},
[821] = {"老陈的空酒桶", {"收集5颗草原狮的獠牙、5个平原陆行鸟的肾脏和1根雷霆蜥蜴的角，把它们交给棘齿城的酿酒师德罗恩。"}},
[822] = {"老陈的空酒桶", {"收集5个闪电腺、1个雷鹰的唾液腺和1个科多兽的肝脏，把它们交给棘齿城里的酿酒师德罗恩。"}},
[823] = {"向奥戈尼尔报告", {"和剃刀岭的奥戈尼尔·魂痕谈一谈。"}},
[824] = {"陶土议会的耶努萨克雷", {"将被污染的水球交给灰谷佐拉姆加前哨站的耶努萨克雷。"}},
[825] = {"海底沉船", {"剃刀岭的加索克要你从海岸边的舰队残骸中打捞出3件侏儒的工具。"}},
[826] = {"扎拉赞恩", {"打败扎拉赞恩。","","杀死8个巫毒巨魔和8个妖术巨魔。","","把扎拉赞恩的头颅带给加德林大师。"}},
[827] = {"骷髅石", {"在骷髅石中的火刃祭司身上收集灼热项圈，","","然后交给玛高兹。"}},
[828] = {"玛高兹", {"和玛高兹谈一谈。"}},
[829] = {"尼尔鲁·火刃", {"给奥格瑞玛的尼尔鲁·火刃带去一个项圈样本。"}},
[830] = {"将军的命令", {"把普罗德摩尔将军的命令带给剃刀岭的加索克。"}},
[831] = {"将军的命令", {"把普罗德摩尔将军的命令交给奥格瑞玛城中的纳兹格雷尔，他就在萨尔的大厅里。"}},
[832] = {"燃影之眼", {"把这颗燃影之眼带给尼尔鲁·火刃。"}},
[833] = {"神圣的墓地", {"博学者诺拉·暴雨图腾要你在赤色石杀掉8个刺背干涉者。"}},
[834] = {"沙漠之风", {"为奥格瑞玛城外的雷兹拉克取回5个装满货物的袋子。"}},
