[836] = {"拯救OOX-09/HL！", {"将OOX-09/HL护送到被遗忘的海岸上的码头，然后向藏宝海湾的奥格索普·奥布诺提斯报告。"}},
[837] = {"野猪人的进犯", {"为剃刀岭的加索克杀掉4个钢鬃野猪人，4个钢鬃斥候，4个钢鬃传令兵和4个钢鬃卫兵。"}},
[838] = {"通灵学院", {"和西瘟疫之地亡灵壁垒的药剂师迪瑟斯谈一谈。"}},
[840] = {"部落的新兵", {"沿着剃刀岭西部的小路一直前进，过桥之后就可以进入贫瘠之地。","","在桥对面的兽人前哨找到卡加尔·战痕，将你的募兵信交给他。"}},
[841] = {"另一个能量源？", {"用10个废土水袋来和加基森的总工程师比格维兹换取另外一个能量源。"}},
[842] = {"十字路口征兵", {"从卡加尔的前沿哨所往西走。","","在丁字路口往左拐，然后朝南走。","","在十字路口的道路交汇处找到瑟格拉·黑棘。"}},
[843] = {"加恩的报复", {"加恩·石塔让你杀死15个巴尔丹挖掘者和5个巴尔丹工头。","","把卡兹戈姆的日记交给加恩·石塔。"}},
[844] = {"平原陆行鸟的威胁", {"收集7个陆行鸟的喙，把它们交给十字路口的瑟格拉·黑棘。"}},
[845] = {"斑马的威胁", {"杀死快步斑马并收集4只斑马蹄，把它们交给十字路口的瑟格拉·黑棘。"}},
[846] = {"加恩的报复", {"加恩·石塔要你将6瓶硝化甘油、6份木浆和6份硝酸钠交给他。"}},
[847] = {"迅猛龙的狡诈", {"和托尔甘谈一谈。"}},
[848] = {"菌类孢子", {"收集4个菌类孢子，把它们交给十字路口的药剂师赫布瑞姆。"}},
[849] = {"加恩的报复", {"摧毁巴尔莫丹的飞行器，然后向加恩·石塔回复。"}},
[850] = {"科卡尔首领", {"把巴拉克的头颅交给十字路口的雷戈萨·死门。"}},
[851] = {"狂热的维罗戈", {"把维罗戈的头颅交给十字路口的雷戈萨·死门。"}},
