[853] = {"药剂师扎玛", {"在药剂的效力消失之前，把提炼过的孢子交给雷霆崖的药剂师扎玛。"}},
[854] = {"十字路口之旅", {"去十字路口和索克谈一谈。"}},
[855] = {"半人马护腕", {"收集15个半人马护腕，把他们交给十字路口的雷戈萨·死门。"}},
