[865] = {"迅猛龙角", {"从赤鳞镰爪龙身上收集5根完整的迅猛龙角，把它们交给棘齿城的米希瑞克斯。"}},
[866] = {"根须样本", {"把根须样本交给棘齿城的麦伯克·米希瑞克斯。"}},
