[868] = {"蝎卵", {"把12枚异种蝎卵和掘地爪交给十字路口的科兰。"}},
[869] = {"偷钱的迅猛龙", {"收集12颗迅猛龙的头颅，把它们交给十字路口的加兹罗格。"}},
[870] = {"遗忘之池", {"向图加·符文图腾报告你的发现。"}},
[871] = {"野猪人的袭击", {"在钢鬃野猪人的营地里杀掉8个寻水者、8个织棘者和3个猎手，然后向十字路口的索克复命。"}},
[872] = {"野猪人的头目", {"杀掉8个钢鬃地卜师、8个钢鬃防御者和他们的头目克里尼格·糟鼻。","","把克里尼格·糟鼻的獠牙交给十字路口的索克。"}},
[873] = {"依沙瓦克", {"把依沙瓦克的心脏交给玛伦·星眼。"}},
[874] = {"玛伦·星眼", {"和玛伦·星眼谈一谈。"}},
[875] = {"鹰身人首领", {"从巫翼杀戮者那里收集6枚鹰身人首领之戒，把它们交给十字路口的达索克·快刀。"}},
[876] = {"塞瑞娜·血羽", {"杀掉塞瑞娜·血羽，把她的头颅交给十字路口的达索克·快刀。"}},
[877] = {"死水绿洲", {"调查死水绿洲，然后返回十字路口向图加·符文图腾报告。"}},
[878] = {"野猪人的内战", {"杀掉6个刺背寻水者、12个刺背织棘者和12个刺背地卜师，然后到陶拉祖营地的碎牙那里复命。"}},
[879] = {"内奸", {"杀掉纳克、卡兹和洛克·奥克班恩，把它们的颅骨交给陶拉祖营地的碎牙。"}},
