[882] = {"伊沙姆哈尔", {"把伊沙姆哈尔的牙齿交给陶拉祖营地的乔恩。"}},
[883] = {"拉克塔曼尼", {"把拉克塔曼尼的蹄子交给陶拉祖营地的乔恩。"}},
