[889] = {"风之魂", nil},
[890] = {"丢失的货物", {"把加兹鲁维的账本交给棘齿城的码头管理员迪兹维格。"}},
[891] = {"北方城堡的火炮", {"棘齿城中的沙罗萨斯船长要你收集10枚塞拉摩徽章并干掉法莫斯队长、炮兵维桑恩和炮兵斯密瑟。"}},
[892] = {"丢失的货物", {"把加兹鲁维的账本交还给棘齿城的加兹鲁维。"}},
[893] = {"野猪人的武器", {"给陶拉祖营地的塔特纳克·钢炉带去一把钢鬃背刺匕首、一根烧焦的钢鬃魔杖和一面钢鬃大盾。"}},
[894] = {"什么什么平衡器", {"在风险投资公司研究基地里找到控制台。"}},
