[898] = {"逃离监牢", {"护送基尔萨瑞斯·火枝安全地返回棘齿城的沙罗萨斯船长那里。"}},
[899] = {"复仇的怒火", {"收集60根刺背野猪人的獠牙，把它们交给十字路口的曼科里克。"}},
