[913] = {"雷鹰的嘶鸣", {"找到一只雷鹰，杀掉它，然后把它的翅膀交给陶拉祖营地的乔恩·星眼。"}},
[914] = {"尖牙德鲁伊", {"将考布莱恩宝石、安娜科德拉宝石、皮萨斯宝石和瑟芬迪斯宝石交给雷霆崖的纳拉·蛮鬃。"}},
[916] = {"树林蜘蛛的毒囊", {"给奥达希尔的基尔沙兰·风行者带回10个树林蜘蛛的毒囊。"}},
[917] = {"树林蜘蛛的卵", {"给奥达希尔的基尔莎兰带回1枚树林蜘蛛的卵。"}},
[918] = {"林精的种子", {"给奥拉密斯湖边的德纳兰带去8粒林精的种子。"}},
[919] = {"林精的新芽", {"给奥拉密斯湖边的德纳兰带去12个林精的新芽。"}},
[920] = {"特纳隆的召唤", {"与奥达希尔顶部的特纳隆·雷拳交谈。"}},
[921] = {"大地之冠", {"装满水晶瓶并将其带回给奥达希尔顶部的特纳隆·雷拳。"}},
[922] = {"雷利亚·绿树", {"给达纳苏斯的雷利亚·绿树带去一粒林精的种子。"}},
[923] = {"青苔之瘤", {"收集5个青苔之瘤，然后把它们交给达纳苏斯的雷利亚·绿树。"}},
