[928] = {"大地之冠", {"将装着半瓶水的瓶子交给多兰纳尔的科瑞萨斯·月怒。"}},
[929] = {"大地之冠", {"用月亮井的水装满翡翠瓶，然后把它交给多兰纳尔的科瑞萨斯·月怒。"}},
