[1171] = {"奥妮克希亚的血脉", {"去和蕨墙村的德拉兹辛比谈一谈。"}},
[1172] = {"奥妮克希亚的血脉", {"蕨墙村的德拉兹辛比要你去毁掉5枚奥妮克希亚的蛋。"}},
