[1243] = {"失踪的使节", {"将密信带给暮色森林的守夜人巴库斯。"}},
[1244] = {"失踪的使节", {"找到迪菲亚记事本，把它带回给暮色森林的守夜人巴库斯。"}},
[1245] = {"失踪的使节", {"将迪菲亚记事本带给暴风城的埃林·提亚斯。"}},
[1246] = {"失踪的使节", {"与暴风城旧城区里的达舍尔·石拳谈一谈。"}},
[1247] = {"失踪的使节", {"与暴风城的埃林·提亚斯谈一谈。"}},
