[1878] = {"收集水袋", nil},
[1879] = {"和彬克交谈", {"和铁炉堡的彬克谈一谈。"}},
[1880] = {"法师文档存储器", {"帮彬克找回她的法师文档存储器。"}},
[1881] = {"安娜斯塔西娅", {"和安娜斯塔西娅·哈特威尔谈一谈。"}},
[1882] = {"巴尼尔农场", {"将巴尼尔金鱼草交给幽暗城法师区的安娜斯塔西娅·哈特威尔。"}},
[1883] = {"安苏瓦", {"和安苏瓦谈一谈。"}},
[1884] = {"魂能骨堆", {"摧毁4个魂能骨堆，然后向森金村的安苏瓦汇报。"}},
[1918] = {"被污染的水元素", {"将被污染的水球交给灰谷碎木哨岗的马斯托克·维尔西斯。"}},
[1919] = {"向詹妮亚报告", {"和暴风城的詹妮亚·坎农谈一谈。"}},
[1920] = {"调查蓝色隐士", {"从詹妮亚·坎农身后拿取一根显形卷轴以及一盒封灵箱。将3个装满的封灵箱交给巫师圣殿里的詹妮亚·坎农。"}},
[1921] = {"收集原料", {"把10匹亚麻布和6颗充能裂隙宝石交给暴风城的维恩·拉尔森。"}},
[1938] = {"乌尔的暗影魔法研究论文", {"将《乌尔的暗影魔法研究论文》交给暴风城的高阶巫师安多玛斯。"}},
[1939] = {"高阶巫师安多玛斯", {"和高阶巫师安多玛斯谈一谈。"}},
[1940] = {"新鲜的蜘蛛丝", {"找到8束新鲜的蜘蛛丝，把它们交给暴风城的维恩·拉尔森。"}},
[1941] = {"法纹长袍", nil},
[1942] = {"星结之衣", nil},
[1943] = {"巨魔法师迪诺", {"和迪诺谈一谈。"}},
[1944] = {"克萨维亚之水", {"将克萨维亚水样交给奥格瑞玛的迪诺。"}},
[1945] = {"欢笑的姐妹", {"给十字路口的基尔哈拉带去12缕欢笑姐妹的头发。"}},
[1946] = {"虚灵长袍", nil},
[1947] = {"沼泽之旅", {"和塔贝萨谈一谈。"}},
[1948] = {"强大的物品", {"将电能草莓和1颗翡翠交给尘泥沼泽的塔贝萨。"}},
[1949] = {"隐藏的秘密", {"和闪光平原的大法师提尔斯谈一谈。"}},
[1950] = {"解封咒语", {"找到提尔斯保险箱的解封咒语，然后向提尔斯复命。"}},
[1951] = {"能量仪祭", {"将《能量仪祭》交给尘泥沼泽的塔贝萨。"}},
[1952] = {"法师的魔杖", {"等塔贝萨的仪式完成后，和她谈一谈。"}},
[1953] = {"返回沼泽", {"和塔贝萨谈一谈。"}},
[1954] = {"地狱火宝珠", {"将一颗地狱火宝珠交给尘泥沼泽的塔贝萨。"}},
[1955] = {"驱除魔鬼", {"杀死宝珠之魔，然后与塔贝萨谈一谈。"}},
[1956] = {"奥达曼的能量源", {"找到一个黑曜石能量源，将其交给尘泥沼泽的塔贝萨。"}},
