[1960] = {"调查炼金店", {"从安娜斯塔西娅·哈特威尔身后拿取一根显形卷轴以及一盒封灵箱。将3个装满的封灵箱交给幽暗城的安娜斯塔西娅·哈特威尔。"}},
[1961] = {"收集原料", {"把10块亚麻布和6块达拉然法力宝石带给乔瑟夫·格里高利。"}},
[1962] = {"魔焰长袍", nil},
[1963] = {"碎手氏族", {"杀死塔赞，把他的背包带给奥格瑞玛暗影裂口的瑟祖克。"}},
[1998] = {"芬维克·萨托斯", {"杀掉芬维克·萨托斯，把他的头颅交给幽暗城潜行者区的米奈特·卡加德。"}},
[1999] = {"交易工具", {"找到达拉然形势报告，把它交给幽暗城潜行者区的米奈特·卡加德。"}},
[2038] = {"宾格斯的补给品", {"找回宾格斯的装备：","$宾格斯的气压炸弹、宾格斯的扳手、宾格斯的榔头和宾格斯的螺丝起子。"}},
[2039] = {"寻找宾格斯", {"去洛克莫丹寻找宾格斯。"}},
[2040] = {"地底突袭", {"从死亡矿井中带回小型高能发动机，将其带给暴风城矮人区中的沉默的舒尼。"}},
[2041] = {"沉默的舒尼", {"去暴风城和舒尼谈一谈。"}},
[2078] = {"基尔卡克的报复", {"找到基尔卡克的大副——机械打手4100型，把他带到基尔卡克那里。"}},
[2098] = {"基尔卡克的钥匙", {"找到基尔卡可钥匙的3段碎片，把它们交给基尔卡克·旋杆。"}},
[2118] = {"瘟疫蔓延", {"活捉一只狂暴蓟熊，把它带到萨纳瑞恩那里。"}},
[2138] = {"清除疫病", {"到森林里去杀掉20头狂暴蓟熊。"}},
[2139] = {"萨纳瑞恩的希望", {"找到雌蓟熊，然后杀掉它。"}},
[2158] = {"休息和放松", {"和狮王之傲旅店的旅店老板法雷谈一谈。"}},
[2159] = {"多兰纳尔的货物", {"把药草送到旅店老板凯达米尔手中。"}},
[2160] = {"塔诺克的补给品", {"给卡拉诺斯的塔诺克·霜锤带去一箱旅店补给品。"}},
[2161] = {"苦工的重担", {"把乌克尔的货物交给剃刀岭的旅店老板格罗斯克。"}},
[2178] = {"炖陆行鸟", {"给急弯河的奥兰达利亚·夜歌带回5块陆行鸟肉。"}},
[2198] = {"破碎的项链", {"找到破碎的项链的来源，从而了解其潜在的价值。"}},
[2199] = {"昂贵的知识", {"给铁炉堡的塔瓦斯德·基瑟尔带去五块银锭。"}},
[2200] = {"回到奥达曼", {"去奥达曼寻找塔瓦斯的魔法项链，被杀的圣骑士是最后一个拿着它的人。"}},
[2201] = {"寻找宝石", {"在奥达曼寻找红宝石、蓝宝石和黄宝石的下落。找到它们之后，通过塔瓦斯德给你的占卜之瓶和他进行联系。"}},
[2202] = {"奥达曼的蘑菇", {"收集12颗紫色蘑菇，把它们交给卡加斯的加卡尔。"}},
[2203] = {"荒芜之地的试剂 II", {"用空的魔瓶吸收荒芜之地的烈焰守护者的血液。装满所有瓶子之后，把它们交给卡加斯的加卡尔。"}},
[2204] = {"修复项链", {"从奥达曼最强大的石人身上获得能量源，然后将其交给铁炉堡的塔瓦斯德。"}},
[2205] = {"军情七处", {"把科瑞恩·塞尔留斯的包裹带给暴风城兵营的马迪亚斯·肖尔。"}},
[2206] = {"连偷带抢", {"找到迪菲亚码头主管，从他那里为马迪亚斯·肖尔拿到迪菲亚船运时间表。"}},
[2218] = {"救赎之路", {"和铁炉堡的霍夫丹·黑须谈一谈。"}},
[2238] = {"国王的财宝", {"在诺莫瑞根附近找到奥宁·雨锤。"}},
[2239] = {"奥宁的报告", {"把奥宁的报告交给铁炉堡的霍夫丹。"}},
[2240] = {"密室", {"阅读巴尔洛戈的日记，探索密室，然后向铁炉堡的勘察员塔伯斯·雷矛汇报。"}},
[2241] = {"詹诺克的花", {"把詹诺克的玫瑰带给达纳苏斯的塞尤娜。"}},
[2242] = {"命运的召唤", {"找到远古的塞希尔，带回任何你可能发现的线索。"}},
[2258] = {"荒芜之地的试剂", {"前往荒芜之地取回加卡尔需要的试剂，然后回到卡加斯把试剂交给他。"}},
[2278] = {"白金圆盘", {"和石头守护者交谈，从他那里了解更多古代的知识。一旦你了解到了所有的内容之后就激活诺甘农圆盘。"}},
[2279] = {"白金圆盘", {"把迷你版的诺甘农圆盘带到铁炉堡的探险者协会去。"}},
[2280] = {"白金圆盘", {"把迷你版的诺甘农圆盘带到雷霆崖的贤者那里。"}},
[2281] = {"赤脊山的联络员", {"到赤脊山的湖畔镇去和卢修斯谈一谈。"}},
[2282] = {"奥瑟尔伐木场", {"打开卢修斯的箱子，拿到偷窃技能证明物，然后把它归还给湖畔镇的卢修斯。"}},
[2283] = {"搜寻项链", {"在奥达曼挖掘场中寻找一条珍贵的项链，然后将其交给奥格瑞玛的德兰·杜佛斯。项链有可能已经损坏。"}},
[2284] = {"搜寻项链，再来一次", {"在奥达曼里找寻宝石的线索。"}},
[2298] = {"国王的搜查", {"到暴风城里去找到“剃刀”雷吉克。"}},
[2299] = {"去找霍夫丹！", {"到铁炉堡去和霍夫丹·黑须谈一谈。"}},
[2318] = {"翻译日记", {"在荒芜之地的卡加斯哨所里寻找一个可以帮你翻译圣骑士日记的人。"}},
[2338] = {"翻译日记", {"将项链借给加卡尔。作为交换，他将帮你翻译日记。"}},
[2339] = {"寻找宝贝", {"从奥达曼找回项链上的所有三块宝石和能量源，然后把它们交给卡加斯的加卡尔。","","红宝石被藏在暗影矮人层层设防的地区。","","黄宝石藏在石腭怪活动地区的一个瓮中。","","蓝宝石在格瑞姆洛克手中，他是石腭怪的领袖。","","能量源可能在奥达曼的某个最强生物的手中。"}},
[2340] = {"交付宝石", {"把项链和宝石送到奥格瑞玛的德兰·杜佛斯那里。"}},
[2341] = {"项链任务的终结", {"去卡加斯看看加卡尔是否成功了。"}},
[2342] = {"寻找宝物", {"从奥达曼南部大厅的箱子中找到加勒特的家族宝藏，然后把它交给幽暗城的帕特里克·加瑞特。"}},
[2359] = {"克拉文之塔", {"偷取迪菲亚塔楼钥匙，进入迪菲亚塔楼，看看暮色森林的箱子里到底有什么东西，然后向暴风城的马迪亚斯·肖尔汇报。"}},
[2360] = {"马迪亚斯和迪菲亚潜行者", {"去西部荒野和密探吉尔妮谈一谈。"}},
[2361] = {"修复项链", nil},
[2378] = {"寻找碎手氏族", {"前往奥格瑞玛，和暗影裂口那的申苏尔谈一谈。"}},
[2379] = {"赞杜沙", {"与暗影裂口的赞杜沙谈一谈。"}},
[2381] = {"抢劫海盗", {"把南海宝藏带回给棘齿城的卑鄙的维尼克斯。不要忘了从维尼克斯的机械设备中拿取一份大饼干和潜行者工具，你的任务需要使用这两件东西。","","如果你被任何奇怪的鹦鹉攻击，就对它使用大饼干！"}},
[2382] = {"棘齿城的维尼克斯", {"到棘齿城去，与卑鄙的维尼克斯谈一谈。"}},
[2383] = {"简易羊皮纸", {"阅读简易羊皮纸，然后和试炼谷的弗郎恩谈一谈。"}},
[2398] = {"失踪的矮人", {"在奥达曼找到巴尔洛戈。"}},
[2399] = {"发芽的树叶", nil},
[2418] = {"能量石", {"给荒芜之地的里格弗兹带去8块德提亚姆能量石和8块安纳洛姆能量石。"}},
[2438] = {"翡翠摄梦符", {"将翡翠摄梦符交给多兰纳尔的塔隆凯·捷根。"}},
[2439] = {"白金圆盘", {"把你的报酬凭证交给铁炉堡银行的丁尼塔·石衣。"}},
[2440] = {"白金圆盘", {"把报酬凭证交给雷霆崖的本娜·冰蹄。"}},
[2458] = {"卧底密探", {"到淤泥沼泽北边的风险投资公司塔楼去，联系碎手氏族的卧底费苏勒。","","看到塔楼之后，用信号枪发射信号，向工头费苏勒示意你已经到达。发出两个闪光信号，然后使用碎手军礼和工头费苏勒接头。","","注意，这些步骤必须依次进行，因为费苏勒会攻击并干掉任何他无法识别的人。"}},
[2459] = {"噬梦者菲罗斯塔", {"多兰纳尔的塔隆凯·捷根要你杀掉7个瘤背秘法师，并找到遗失的珠宝。"}},
[2460] = {"碎手军礼", {"对着申苏尔练习碎手军礼。"}},
[2478] = {"基本不可能的任务", {"从工头希里克斯那里偷出希里克斯的塔楼钥匙，进入塔楼，然后杀掉两个变异风险投资公司工人、两个风险投资公司巡逻员、两个风险投资公司看守。","","杀掉大工头普兹克·加里维克斯，取了他的首级，然后打开加里维克斯的箱子，拿走赞吉尔的改良药剂。将药剂和加里维克斯的头颅交给奥格瑞玛的申苏尔，等候进一步的指示。"}},
[2479] = {"希诺特的帮助", {"到希尔斯布莱德丘陵的塔伦米尔去，把赞吉尔的药剂样品交给瑟尔格·希诺特。","","要去塔伦米尔，可以搭乘飞艇到幽暗城，然后沿着大路向南穿过银松森林，直到希尔斯布莱德丘陵。跟着路标走！"}},
[2480] = {"希诺特的帮助", {"等待瑟尔格·希诺特完成解药。"}},
[2498] = {"向德纳兰回报", {"雷利亚·绿树要你和奥拉密斯湖的德纳兰谈一谈。"}},
[2499] = {"奥肯斯古尔", {"奥拉密斯湖的德纳兰要你去拿到奥肯斯古尔身上的巨大的瘤。"}},
[2500] = {"荒芜之地的材料", {"从荒芜之地拿到加克所需的材料，然后回到塞尔萨玛去见他。"}},
[2501] = {"荒芜之地的材料 II", {"在荒芜之地的守护火龙身上使用空的魔瓶。将这些容器都盛满之后，把它们交给塞尔萨玛的加克。"}},
[2518] = {"月神的泪水", {"达纳苏斯月神殿的女祭司艾茉拉让你把萨丝拉的银色丝囊交给她。"}},
[2519] = {"月神殿", {"艾奎恩妮让你和月神殿的女祭司艾茉拉谈一谈。"}},
[2520] = {"萨丝拉的祭品", {"女祭司艾茉拉让你将萨丝拉的银色丝囊放在大殿的喷泉处，然后回去见她。"}},
[2523] = {"被腐化的轻歌花", nil},
[2541] = {"沉睡的德鲁伊", {"将一个萨满巫毒符咒交给班奈希尔兽穴的奥本·怒爪。"}},
[2561] = {"利爪德鲁伊", {"奥本·怒爪要求你去杀掉他那失去灵魂的身体，然后对其尸体使用巫毒咒符。"}},
[2581] = {"弯牙土狼的颚骨", {"收集3个弯牙土狼的颚骨、2片诅咒之地的野猪肺和1个厚甲蝎螯，把它们交给血法师德拉吉亚。"}},
[2582] = {"远古之怒", {"收集3个弯牙土狼的颚骨、2片诅咒之地的野猪肺和1个厚甲蝎螯，把它们交给血法师德拉吉亚。"}},
[2583] = {"野猪的活力", {"收集3片诅咒之地的野猪肺、2个厚甲蝎螯和1颗石化蜥蜴的大脑，把它们交给血法师德拉吉亚。"}},
[2584] = {"野猪之魂", nil},
[2585] = {"决定性的打击", {"收集3个厚甲蝎螯、2个秃鹫的砂囊和1片诅咒之地的野猪肺，把它们血法师德拉吉亚。"}},
[2586] = {"厚甲蝎盐", {"收集3个厚甲蝎螯、2个秃鹫的砂囊和1片诅咒之地的野猪肺，把它们血法师德拉吉亚。"}},
[2601] = {"石化蜥蜴的大脑", {"收集10颗石化蜥蜴的大脑和2个秃鹫的砂囊，把它们交给血法师莱诺雷。"}},
[2602] = {"清晰的思想", nil},
[2603] = {"秃鹫的活力", {"收集10个秃鹫的砂囊和2块弯牙土狼的颚骨，把它们交给血法师莱诺雷。"}},
[2605] = {"口渴的地精", {"找到1个饱满的露水腺，把它交给加基森的马林·诺格弗格。"}},
