[2969] = {"精灵龙的自由", {"从恐怖图腾营地的围栏里释放被俘获的小精龙。至少6个小精龙和辛达尔·月纹必须活着。","","如果6分钟之内你还没能达成这个目标，辛达尔就会决定撤退，任务也会随即失败。"}},
