[5441] = {"懒惰的苦工", {"在懒惰的苦工睡觉时，用工头的木棒敲他们。敲醒5个苦工，然后把工头的木棒还给试炼谷的工头塔兹利尔。"}},
[5461] = {"莱斯·霜语", {"到阿拉希高地的激流堡遗迹里面寻找巫妖生前的遗物。如果你能找到这样的东西，就把它交给马杜克镇长。"}},
[5462] = {"亡灵莱斯·霜语", {"到东瘟疫之地的圣光之愿礼拜堂去找到莱尼德·巴萨罗梅，给他看看巫妖生前的遗物，并告诉他你收集到的情报。"}},
[5463] = {"米奈希尔的礼物", {"到斯坦索姆城里去找到米奈希尔的礼物，把巫妖生前的遗物放在那块邪恶的土地上。"}},
[5466] = {"巫妖莱斯·霜语", {"在通灵学院里找到莱斯·霜语。当你找到他之后，使用禁锢灵魂的遗物破除其亡灵的外壳。如果你成功地破除了他的不死之身，就杀掉他并拿到莱斯·霜语的头颅。把那个头颅交给马杜克镇长。"}},
[5481] = {"葛尔多的任务", {"收集3根阴暗草，把它们交给布瑞尔墓地的初级药剂师霍兰德。"}},
[5482] = {"末日草", {"收集10株末日草，把它们交给初级药剂师霍兰德。"}},
[5501] = {"集骨者", {"从科多墓地收集10根科多兽骨，把它们交给兽人小屋的比布里·弗斯巴克。"}},
[5503] = {"银色黎明委任徽章", nil},
[5505] = {"通灵学院的钥匙", nil},
[5508] = {"堕落者的天灾石", nil},
[5509] = {"侵略者的天灾石", nil},
[5510] = {"爪牙的天灾石", nil},
[5511] = {"通灵学院的钥匙", nil},
[5514] = {"昂贵的模具", {"把灌魔的骸骨碎片和15枚金币交给加基森的克林科·古德斯迪尔。"}},
[5515] = {"卡斯迪诺夫的恐惧之袋", {"在通灵学院找到詹迪斯·巴罗夫并打败她。从她的尸体上找到卡斯迪诺夫的恐惧之袋，然后将其交给艾瓦·萨克霍夫。"}},
[5518] = {"戈多克食人魔装", {"把4份符文布卷、8块硬甲皮、2卷符文线和一份食人魔鞣酸交给诺特·希姆加克。他现在被拴在厄运之槌的戈多克食人魔那边。"}},
[5522] = {"莱尼德·巴萨罗梅", {"把冰冻的龙蛋交给东瘟疫之地的莱尼德·巴萨罗梅。"}},
[5525] = {"逃出生天！", nil},
[5526] = {"魔藤碎片", {"在厄运之槌中找到魔藤，然后从它上面采集一块碎片。只有干掉了奥兹恩之后，你才能进行采集工作。使用净化之匣安全地封印碎片，然后将其交给月光林地永夜港的拉比恩·萨图纳。"}},
[5527] = {"净化之匣", {"到希利苏斯的南风村去寻找净化之匣。然后将其交给月光林地永夜港的拉比恩·萨图纳。"}},
[5528] = {"戈多克好酒", nil},
[5529] = {"瘟疫之龙", {"杀掉20只瘟疫龙崽，然后向圣光之愿礼拜堂的贝蒂娜·比格辛克复命。"}},
[5531] = {"贝蒂娜·比格辛克", {"将冰冻的龙蛋交给贝蒂娜·比格辛克。"}},
[5533] = {"通灵学院", {"和西瘟疫之地冰风岗的化学家阿尔比顿谈一谈。"}},
[5534] = {"基姆加尔“丢失”的装备", {"寻找埃达拉斯废墟中的纳迦携带的那些符石，然后把它们交给艾萨拉的基姆加尔。"}},
[5535] = {"永不安息的灵魂", {"杀掉6个上层精灵的幻影和6个上层精灵鬼巫，然后向艾萨拉的罗哈图复命。"}},
[5536] = {"充满仇恨的土地", {"杀掉6个哈达尔萨特、2个哈达尔欺诈者和2个哈达尔魔仆，然后向灰谷与艾萨拉交界处的罗哈图复命。"}},
[5537] = {"骸骨碎片", {"将15块骷髅碎片交给西瘟疫之地冰风岗的化学家阿尔比顿。"}},
[5538] = {"昂贵的模具", {"把灌魔的骸骨碎片和15枚金币交给加基森的克林科·古德斯迪尔。"}},
[5541] = {"海格纳的弹药", {"把海格纳的弹药交给丹莫罗的海格纳·重枪。"}},
[5542] = {"恶魔之犬", {"杀掉20条瘟疫幼犬、5条瘟疫犬和5条狂怒的瘟疫犬。任务完成之后向提里奥·弗丁复命。"}},
[5543] = {"血染的天空", {"杀死30只瘟疫蝙蝠，然后向提里奥·弗丁复命。"}},
[5544] = {"腐肉虫", {"在东瘟疫之地搜索腐肉虫和腐肉吞噬者。杀了它们并收集它们的肉。当你收集到15块食腐虫肉块之后，就回到提里奥·弗丁那里。"}},
[5545] = {"木材危机", {"收集8捆木材，把它们交给东谷伐木场的管理员莱琳。"}},
[5561] = {"诱捕科多兽", {"将科多兽诱引器和5头被驯服的科多兽交给瑟卡布斯库的营地中的斯米德·瑟卡布斯库。"}},
[5581] = {"燃烧军团的传送门", {"放逐6个玛诺洛克集会所的传送门，然后回到葬影村的泰迦·慧鬃那里。"}},
[5582] = {"健康的龙鳞", {"把健康的龙鳞交给东瘟疫之地圣光之愿礼拜堂中的贝蒂娜·比格辛克。"}},
[5601] = {"小妹妹帕米拉", {"在达隆郡里找到帕米拉·雷德帕斯。"}},
[5621] = {"月光之衣", {"找到哨兵莎恩雅并使用次级治疗术（等级 2）来治疗她。然后对她施放真言术：韧，最后向多兰纳尔的劳尔娜·晨光复命。"}},
[5622] = {"月神的恩赐", {"与泰达希尔的劳尔娜·晨光谈一谈。"}},
[5623] = {"圣光的恩赐", {"与艾尔文森林的女牧师洁塞塔谈一谈。"}},
[5624] = {"圣光之衣", {"找到卫兵罗伯兹并使用次级治疗术（等级 2）来治疗他。然后对他施放真言术：韧，最后向闪金镇的女牧师洁塞塔复命。"}},
[5625] = {"圣光之衣", {"找到巡山人多尔夫并使用次级治疗术（等级 2）来治疗他。然后对他施放真言术：韧，最后向卡拉诺斯的马克萨恩·安沃尔复命。"}},
[5626] = {"圣光的恩赐", {"与丹莫罗的马克萨恩·安沃尔谈一谈。"}},
