[5629] = {"回家", {"与达纳苏斯的女祭司阿兰希雅谈一谈。"}},
[5641] = {"惩击", nil},
[5642] = {"暗影守卫", {"与奥格瑞玛的乌尔库谈一谈。"}},
[5644] = {"黑暗献祭", {"与幽暗城的艾萨莱斯特谈一谈。"}},
[5646] = {"黑暗献祭", {"与幽暗城的艾萨莱斯特谈一谈。"}},
[5648] = {"灵魂之衣", {"找到步兵科雅，用次级治疗术（等级 2）治疗她，然后为她加上真言术：韧，最后向剃刀岭的泰金复命。"}},
[5649] = {"部族的传统", {"与杜隆塔尔的泰金谈一谈。"}},
[5650] = {"黑暗之衣", {"找到亡灵士兵科尔并使用次级治疗术（等级 2）来治疗他。然后对他施放真言术：韧，最后向布瑞尔的黑暗牧师贝里尔复命。"}},
[5651] = {"黑暗的恩赐", {"与提瑞斯法林地的黑暗牧师贝里尔谈一谈。"}},
