[7905] = {"暗月马戏团", {"到暗月马戏团的场地里去，将免费券交给吉瓦斯·格里加特。"}},
[7937] = {"财富在等着你……", {"到艾尔文森林的东谷伐木场去寻找你的财宝吧。"}},
[7938] = {"财富在等着你……", {"到西部荒野的死亡矿井中去寻找你的财宝吧。"}},
