[8152] = {"激流逃生", {"带着这些泡过水的线索，前往圣光之愿礼拜堂四处问问。"}},
[8153] = {"苔蹄快步者的鹿角", {"将一副完好的苔蹄快步者鹿角交给艾萨拉的奥汀克。奥汀克居住在埃达拉斯废墟东北部的悬崖顶。"}},
