[8231] = {"碎浪多头怪", {"将6块碎浪多头怪的鳞片交给艾萨拉的奥汀克。奥汀克居住在埃达拉斯废墟东北部的悬崖顶部。"}},
[8232] = {"神庙中的绿龙", {"将摩弗拉斯的牙齿交给艾萨拉的奥汀克。他住在埃达拉斯废墟东北部悬崖的顶端。"}},
[8233] = {"简单的要求", {"前往拉文霍德庄园，和乔拉齐·拉文霍德公爵谈一谈。"}},
[8234] = {"密封的蓝袋子", {"从艾萨拉的木喉萨满祭司那儿取回密封的蓝袋子，将它交给艾萨拉的大法师克希雷姆。"}},
[8235] = {"密文碎片", {"将10块密文碎片交给艾萨拉的大法师克希雷姆。"}},
[8236] = {"碧蓝钥匙", {"将碧蓝钥匙交给乔拉齐·拉文霍德公爵。"}},
[8249] = {"垃圾箱", nil},
[8250] = {"法师的会见", {"找到萨纳斯，让他将你传送到大法师克希雷姆那儿。"}},
[8251] = {"魔法的尘埃", {"为大法师克希雷姆收集10份闪光尘埃。"}},
[8252] = {"纳迦的珊瑚", {"收集6块魔化珊瑚，然后把它们交给大法师克希雷姆。"}},
[8253] = {"毁灭摩弗拉斯", {"从摩弗拉斯身上取回奥术碎片，然后返回大法师克希雷姆那儿。"}},
[8254] = {"塞纳里奥议会的求助", {"找到艾萨拉的奥汀克。"}},
[8255] = {"苔蹄快步者", {"收集4份健康的野鹿腺体，把它们交给艾萨拉的奥汀克。奥汀克住在埃达拉斯废墟东北部悬崖的顶部。"}},
[8256] = {"亡灵的腐液", {"为艾萨拉的奥汀克带回一份亡灵腐液。奥汀克住在埃达拉斯废墟东北部悬崖的顶端。"}},
[8257] = {"摩弗拉斯之血", {"前往沉没的阿塔哈卡神庙，杀死绿龙摩弗拉斯，将他的血液交给费伍德森林中的格雷塔·苔蹄。沉没的神庙的入口就在悲伤沼泽中。"}},
[8258] = {"达克雷尔的威胁", {"在斯坦索姆地下室的尸骨储藏所的中心使用预言水晶球。然后你必须与被召唤出来的幽灵作战。击败这些幽灵之后，死亡骑士达克雷尔才会出现，你的任务就是击败他。","","把死亡骑士达克雷尔的头颅交给奥格瑞玛智慧谷的萨格尼。"}},
[8271] = {"雷矛英雄", nil},
[8272] = {"霜狼英雄", nil},
[8273] = {"奥兰的感谢", nil},
[8275] = {"夺回希利苏斯", {"与希利苏斯塞纳里奥要塞的唤风者梅恩·长角谈一谈。"}},
[8276] = {"夺回希利苏斯", {"与希利苏斯塞纳里奥要塞的唤风者梅恩·长角谈一谈。"}},
[8277] = {"沙漠中的剧毒", {"希利苏斯塞纳里奥要塞的比提克斯·斯巴格要求你带8个石鞭蝎之刺和8个掠沙蜘蛛的牙齿给他。"}},
[8279] = {"暮光词典", {"把暮光词典的三个章节交给希利苏斯的隐士奥泰尔。"}},
[8280] = {"保护补给线", {"希利苏斯塞纳里奥要塞的唤风者梅恩·长角要求你去杀死15只掘泥打击者。"}},
[8281] = {"确保安全", {"希利苏斯塞纳里奥要塞的唤风者梅恩·长角要求你去杀死20只掘泥摧毁者。"}},
[8283] = {"通缉：沙漠之骇，死亡弯钩", {"将死亡弯钩的蝎钳交给卫兵队长维斯·库鲁兹。"}},
[8284] = {"暮光的秘密", {"希利苏斯塞纳里奥要塞的地质学家拉克斯班要你去收集8块暮光石板碎片。"}},
[8285] = {"沙漠隐士", {"把复原的石板带给希利苏斯的隐士奥泰尔。"}},
[8304] = {"亲爱的纳塔莉亚", {"希利苏斯塞纳里奥要塞的指挥官玛尔利斯想要你询问铜须营地的矮人。你可以在塞纳里奥要塞以南找到铜须营地。","","一旦你收集到有用的信息，就回到指挥官玛尔利斯那儿。"}},
[8307] = {"沙漠食谱", {"前往塞纳里奥要塞以西的暮光之锤营地，调查沙虫的烹饪方法。"}},
[8308] = {"布莱恩·铜须的信", {"将布莱恩·铜须的信件带往希利苏斯南部的铜须营地。"}},
[8313] = {"分享知识", {"将破碎的食谱交给塞纳里奥要塞旅店中的卡兰德拉斯。"}},
[8317] = {"下厨", {"塞纳里奥要塞的卡兰德拉斯需要制作10只沙漠肉丸子。"}},
[8318] = {"秘密交流", {"把10片暮光密文信交给塞纳里奥要塞的鲍尔·蛮鬃。"}},
[8320] = {"暮光地王", {"杀死10个暮光地王，然后向塞纳里奥要塞的霍姆·蛮鬃复命。"}},
[8331] = {"奥蕾尔·金叶", {"与塞纳里奥要塞的奥蕾尔·金叶谈一谈。"}},
[8332] = {"议会的公爵", {"把1个大块魔光碎片和3顶深渊纹章交给塞纳利奥要塞的奥蕾尔·金叶。"}},
[8365] = {"海盗的帽子！", {"塔纳利斯热砂港的傲慢的店主要你去帮他收集20顶南海海盗帽。"}},
[8366] = {"南海复仇", {"塔纳利斯热砂港的安全主管吉罗姆·比格维兹要你去干掉10个南海海盗、10个南海劫掠者、10个南海码头工人和10个南海流氓。"}},
[8367] = {"无上的荣耀", {"把3枚奥特兰克山谷荣誉奖章，3枚阿拉希盆地荣誉奖章，3枚战歌峡谷荣誉奖章和3枚暗矛群岛荣誉奖章交给战场外的部落战争使者。"}},
