[8467] = {"给纳菲恩的羽毛", nil},
[8469] = {"给萨尔法的珠串", nil},
[8470] = {"死木仪祭图腾", {"把死木仪祭图腾拿到木喉要塞去，看看是否有熊怪想要研究一下它。只有当你在木喉要塞的声望达到中立或者更高级别的时候，木喉要塞的熊怪才会和你说话。"}},
[8471] = {"冬泉仪祭图腾", {"把冬泉仪祭图腾拿到木喉要塞去，看看是否有熊怪想要研究一下它。只有当你在木喉要塞的声望达到中立或者更高级别的时候，木喉要塞的熊怪才会和你说话。"}},
[8551] = {"船长的箱子", {"将斯莫特的箱子交给藏宝海湾的海克拜瑞·斯莫特。"}},
[8552] = {"刺着字母的腰带", {"将刺着字母的腰带还给他的主人。"}},
[8553] = {"船长的弯刀", {"与斯普罗格谈一谈。"}},
[8554] = {"挑战奈古拉什", {"将10块烧烤秃鹰翅膀和5瓶密林葡萄酒带到斯莫特船长的救生艇上去。","","然后杀死奈古拉什，将斯莫特的弯刀交给荆棘谷的斯莫特船长。"}},
[8893] = {"超级测蛋器", nil},
[8921] = {"灵质提纯器", {"将1个精密奥金转换器、4份强效不灭精华、10瓶石鳞鱼油、25份火山灰和40枚金币交给加基森的穆克斯·玛纳斯卡波。"}},
[8922] = {"超自然的设备", {"将封起来的血液容器交给加基森的穆克斯·玛纳斯卡波。"}},
[8923] = {"超自然的设备", {"将封起来的毒液容器交给加基森的穆克斯·玛纳斯卡波。"}},
[8924] = {"猎取灵质", {"使用灵质提纯器在希利苏斯收集12份烧焦的灵质，在冬泉谷收集12份冰冻的灵质，以及在东瘟疫之地收集12份稳定的灵质。然后将这些东西与灵质提纯器一起交给加基森的穆克斯·玛纳斯卡波。"}},
[8925] = {"便携的能量源", {"前往燃烧平原，找到熔岩领主博奥克，把它的岩浆核心交给加基森的穆克斯·玛纳斯卡波。"}},
[8928] = {"小巧的商人", {"到冬泉谷南部的暗语峡谷入口附近去，在那里的一处洞穴内的某个小鬼那里购买一根恶魔元素之杖，并把它交给加基森的穆克斯·玛纳斯卡波。"}},
[8930] = {"寻找安泰恩", {"在斯坦索姆的入口处使用超维度幽灵显形器，然后与安泰恩·哈尔蒙的灵魂交谈。"}},
[8946] = {"生命的证据", {"将伊思达的盒子交给东瘟疫之地的安泰恩·哈尔蒙。"}},
[8947] = {"安泰恩的奇怪请求", {"将3块黑铁锭、20张魔化皮、3块月布和4块熟化毛皮交给东瘟疫之地的安泰恩·哈尔蒙。"}},
[8978] = {"向莫克瓦尔回复", {"将超维度幽灵显形器交给奥格瑞玛的莫克瓦尔。"}},
[9051] = {"毒性测试", {"将魔暴龙之刺扎入一只魔暴龙的体内。"}},
