[93601] = {"推卸责任", {"在刺背避难所寻找一位有头有脸的野猪人。"}},
[93604] = {"阿迦玛甘之血", {"深入剃刀高地，取回剧毒的阿迦玛甘之血。将其交给凄凉之地刺背避难所的勇敢的科格苏格。科格苏格特意强调过，剃刀沼泽里的阿迦玛甘之血糊弄不了他。"}},
[93606] = {"尖叫绝交", {"平息野猪人之间的争端，为库尔加带去仁慈的花束和剧毒的阿迦玛甘之血。制作花束所需的花朵，可在凄凉之地辛德拉附近的荒弃花园中采集。"}},
[93609] = {"遗忘项链", {"将遗忘项链带给凄凉之地辛德拉神殿的米瑟拉。"}},
[93615] = {"大猫与小猫", {"在海加尔山的荒野中找到沙拉卡尔的小猫。"}},
[93617] = {"猎物与捕食者", {"阻止雄鹿们扮演捕食者的行为。"}},
[93644] = {"破烂的日记", {"这些文字暗示，这本日记的作者可能就在辛德拉的某处。"}},
[93663] = {"运输途中失踪", {"找到失踪的信使，确保达尔的货物被送到避难营。"}},
[93678] = {"德莱尼水晶笔记摘要", {"将阿佐尔誊写的笔记带回悲伤沼泽避难营，交给玛格图尔。"}},
[93679] = {"另一位同族的幻象", {"与玛格图尔一起观看昂库的幻象。"}},
[93680] = {"城市大门钥匙", {"为塔伦米尔的大法师沃迪恩·伍德格莱尔取得达拉然下水道钥匙。"}},
[93684] = {"寻获之人", {"在诅咒之地找到那名正在寻找德莱尼水晶的德莱尼人。"}},
[93685] = {"为库米沙效力", {"在诅咒之地找到一颗无暇的德莱尼水晶球，并将其交给收藏家库米沙。","","注意，这种宝石是整个艾泽拉斯最稀有的水晶之一。这片土地上的任何生物都可能携带无暇的德莱尼水晶球。"}},
[93735] = {"损坏的构造体", {"在瓦拉纳尔西侧找到里阿尼·夜风。"}},
[93736] = {"不受欢迎的精魂", {"从影风森林的空洞风灵身上收集10份空洞风灵精华。"}},
[93737] = {"损坏的构造体", {"与里阿尼·夜风交谈，听听他有什么要说的。"}},
[93738] = {"损坏的构造体", {"向瓦拉纳尔的阿耶莎·晨歌复命。"}},
[93739] = {"部落之旅", {"到格罗玛什要塞向纳兹格雷尔询问指引，再依照他的指示，分别拜访沃金、凯恩·血蹄和希尔瓦娜斯·风行者女士。"}},
[93740] = {"血债血偿", {"从阵风浆果低地的奥拉凯斯密教徒尸体上收集10个奥拉凯斯风石护符。"}},
[93746] = {"强硬的回应", {"在前往阿基尔神殿的路上与贝拉萨恩·明愿对峙。"}},
[93747] = {"化兵为绿", {"在毁坏的弩车、毁坏的投石车和毁坏的飞行器附近种下附魔种子。"}},
[93759] = {"大自然的馈赠", {"从纯净的海加尔雄鹿身上收集2块海加尔鹿肉排，并收集6个血色飞镖块茎，用来制作隐士的炖肉。"}},
[93773] = {"契约", {"向海加尔山的凯萨拉斯复命。"}},
[93786] = {"血染的警告", {"消灭12名草甸溪农场雇农，然后带着你胜利的消息向克罗姆罗什复命。"}},
[93787] = {"探囊取物", {"从草甸溪的联盟农场偷取6个饲料袋，然后向克罗姆罗什复命。"}},
[93788] = {"借刀杀人", {"从特纳的伐木场的伐木工那里，为洛格玛的克雷扎·暗棘夺回10把木匠的斧头。"}},
[93791] = {"与贝兰交谈", {"与瓦拉纳尔的贝兰·风木交谈。"}},
[93797] = {"风中之枝", {"将注入风之力的树枝带给瓦拉纳尔的贝兰·风木。"}},
[93825] = {"缚皮之赐", {"收集12簇月纱苔藓，将其交给苏玛·苔鬃。"}},
[93826] = {"威震死木", {"击败8名死木图腾师和8名死木邪能看护者，然后向长者松语者复命。"}},
[93827] = {"风袭结界", {"收集16个附魔鹰身人护符，将其交给索邦·树液之爪。"}},
[93828] = {"地穴草药", {"从树皮地洞周围收集10株风干的悬挂草药，并将其交给芬纳·苔鬃。"}},
[93830] = {"海加尔之水", {"在死木熊怪兽穴外的池塘里，装满芬纳·苔鬃提供的水袋。"}},
[93831] = {"甜爪果酱", {"在海加尔山收集30串熊果，将其交给奥斯·迷雾之爪。"}},
[93832] = {"粉碎石卫士", {"在海加尔山上层被毁的联盟基地中摧毁6只永恒哨兵石像鬼，然后向长者迷雾之爪复命。"}},
[93833] = {"残忍的智慧", {"将5具猫头鹰尸体带给海加尔山树皮地洞的长者松语者。"}},
[93834] = {"掘地甲虫", {"为达拉·白颚收集10份掘地甲虫碎片。"}},
[93835] = {"直面洛苏娜", {"穿过传送门前往上方的罗哈什尖塔，与伊拉德林·晚风和阿耶莎·晨歌会合，共同对抗高阶女祭司洛苏娜。"}},
[93836] = {"泽风岛的命运", {"在瓦拉纳尔与塔拉尼斯·影歌交谈。"}},
[93848] = {"大功告成", {"返回凯萨拉斯处，向他报告永恒之巅发生的事情。"}},
[93862] = {"归还箱子", nil},
[93925] = {"给布莱鲁法的珠子", nil},
[93926] = {"西部瞭望塔", {"在西部瞭望塔找到维和者瓦尼尔。"}},
[93927] = {"最后的请求", {"收集在阵亡维和者附近找到的便笺，看看接下来该怎么做。"}},
[93948] = {"送还图章", {"将影歌家族的图章戒指交给瓦拉纳尔的塔拉尼斯·影歌。"}},
[93949] = {"窃听虫", {"在瓦拉纳尔击杀天空跳跃者，直到消灭8只被施法的天空跳跃者。"}},
[93951] = {"一点小小的美丽", {"在申达尔高地收集8根角鹰兽绒毛。"}},
[93952] = {"力量带来平衡", {"击败9名死木兽穴守卫并向布莱鲁法复命。"}},
[93958] = {"内殿", {"在阿基尔神殿的内殿与瓦伦妮亚·风暴之拳交谈。"}},
[93963] = {"联盟之旅", {"到暴风要塞向兰达尔·埃默森询问指引，再依照他的指示，分别拜访国王麦格尼·铜须、大工匠梅卡托克和泰兰德·语风。"}},
[93971] = {"法霍德侦察报告", {"把报告交给洛格玛的克罗姆罗什。"}},
[93976] = {"地精商人", {"将利刃交给洛格玛东面码头处克雷扎·暗棘的熟人。"}},
[94003] = {"破天者壁垒", {"从阿基尔神殿的扎尔·风暴之盾手里夺回破天者壁垒。"}},
[94004] = {"工匠文书：食人魔力量药剂", {"备齐客户要求的物品，并将其送至地图上标记的地点。你必须携带本文书才能完成交易。"}},
[94006] = {"伟大的乌萨拉之灵", {"在瓦拉纳尔东北方的瀑布附近与乌尔森德里斯交谈。"}},
[94007] = {"驯服野兽", {"向瓦拉纳尔的奎尔阿娜·疾风报到。"}},
[94013] = {"驯服野兽", {"在阵风浆果低地使用驯兽棒驯服一只瓦尔德伦头狼。磨炼你的驯兽技巧，然后把驯兽棒还给瓦拉纳尔的奎尔阿娜·疾风。"}},
[94050] = {"训练野兽", {"与瓦拉纳尔的奎尔多拉·疾风交谈。"}},
