[97914] = {"拓宽视野", {"将桑迪斯的信件送达暴风城的巴隆斯·阿历克斯顿手中。","","桑迪斯提到奥伯丁有一艘可以载你过去的船。"}},
[97915] = {"露营基础：炼金术", {"展示出你对专业技能的精通后，前往暴风城附近的艾尔文森林寻找炼金师玛洛瑞，学习如何制作与你专业相符的露营物品。"}},
