[97926] = {"勉强度日", {"将阿历克斯顿的回信带给黑海岸奥伯丁的桑迪斯·织风。"}},
[97928] = {"露营基础：锻造", {"展示出你对专业技能的精通后，前往雷霆崖寻找瑟拉格·石蹄，学习如何制作与你专业相符的露营物品。"}},
